export function getProduct(idOrSlug) {
  return products.find((p) => p.id === idOrSlug || p.slug === idOrSlug);
}

export function getSize(product, ml) {
  if (ml === 'refill') return { ml: 'refill', label: '100 ml Refill', price: product.refillPrice };
  const s = product.sizes.find((x) => String(x.ml) === String(ml)) || product.sizes[product.sizes.length - 1];
  return { ...s, label: `${s.ml} ml` };
}

export function priceFrom(product) {
  return Math.min(...product.sizes.map((s) => s.price));
}

